import React from "react";
import { NavLink } from "react-router-dom";
import "./../css/nav.css";


class Home extends React.Component {
  render() {
    return (
<>home</>
    );
  }
}


const Footer = () => {
  return (
    <nav class="bottom-nav" id="bottomNav">
      <a href="#" class="nav-item active" data-i="home">
        <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/></svg>
        <span class="nav-label">خانه</span>
      </a>
      <a href="#" class="nav-item" data-i="appt">
        <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>
        <span class="nav-label">نوبت‌ها</span>
      </a>
      <a href="#" class="nav-item" data-i="svc">
        <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/></svg>
        <span class="nav-label">خدمات</span>
      </a>
      <a href="#" class="nav-item" data-i="journey">
        <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 14c1.5-1.5 3-3.2 3-5.5A5.5 5.5 0 0 0 12 5 5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4 3 5.5l7 7Z"/></svg>
        <span class="nav-label">سفر من</span>
      </a>
      <a href="#" class="nav-item" data-i="profile">
        <svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
        <span class="nav-label">پروفایل</span>
      </a>
    </nav>
  );
};

export default Footer;
